<script setup lang="ts">
import { reactive,ref } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { ElMessage } from '@/app/messages'
import { adminFeedback,adminFeedbackDetail,handleFeedback } from '@/api/feedback'
import { readableError } from '@/api/errors'
import { formatShanghai } from '@/utils/format'
import type { Feedback,FeedbackStatus,FeedbackType } from '@/api/types'

const page=ref(1),drawer=ref(false),busy=ref(false),selected=ref<Feedback|null>(null)
const filters=reactive<{status:''|FeedbackStatus;type:''|FeedbackType;problemNo:string;userId:string}>({status:'',type:'',problemNo:'',userId:''})
const handling=reactive<{status:'PROCESSING'|'RESOLVED';adminReply:string}>({status:'PROCESSING',adminReply:''})
const query=useQuery({queryKey:['admin','feedback',page,filters],queryFn:()=>adminFeedback({current:page.value,pageSize:20,status:filters.status||undefined,type:filters.type||undefined,problemNo:filters.problemNo?Number(filters.problemNo):undefined,userId:filters.userId||undefined})})
const typeLabel:Record<FeedbackType,string>={PROBLEM:'题目问题',BUG:'系统故障',SUGGESTION:'功能建议',OTHER:'其他'}
const statusLabel:Record<FeedbackStatus,string>={PENDING:'待处理',PROCESSING:'处理中',RESOLVED:'已解决'}
function search(){page.value=1;void query.refetch()}
async function open(row:Feedback){try{selected.value=await adminFeedbackDetail(row.id);handling.status=selected.value.status==='RESOLVED'?'RESOLVED':'PROCESSING';handling.adminReply=selected.value.adminReply??'';drawer.value=true}catch(e){ElMessage.error({ message: readableError(e) })}}
async function save(){if(!selected.value)return;if(handling.status==='RESOLVED'&&!handling.adminReply.trim()){ElMessage.warning({ message: '解决反馈时必须填写回复' });return}busy.value=true;try{selected.value=await handleFeedback({id:selected.value.id,status:handling.status,adminReply:handling.adminReply.trim(),expectedRowVersion:selected.value.rowVersion});ElMessage.success({ message: '处理结果已保存' });await query.refetch()}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
</script>
<template><div class="page admin-feedback"><div class="page-head"><div><h1 class="page-title">反馈处理</h1><p class="page-lead">查看用户反馈、回复并更新处理状态</p></div></div>
  <section class="surface filters"><el-select v-model="filters.status" placeholder="全部状态" clearable><el-option label="待处理" value="PENDING"/><el-option label="处理中" value="PROCESSING"/><el-option label="已解决" value="RESOLVED"/></el-select><el-select v-model="filters.type" placeholder="全部类型" clearable><el-option v-for="(label,value) in typeLabel" :key="value" :label="label" :value="value"/></el-select><el-input v-model="filters.problemNo" placeholder="题号" clearable/><el-input v-model="filters.userId" placeholder="用户 ID" clearable/><el-button type="primary" @click="search">查询</el-button></section>
  <section class="surface table-shell"><el-table :data="query.data.value?.records" v-loading="query.isPending.value" empty-text="暂无反馈" @row-click="open"><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='RESOLVED'?'success':row.status==='PROCESSING'?'warning':'info'">{{statusLabel[row.status as FeedbackStatus]}}</el-tag></template></el-table-column><el-table-column label="AI 分流" width="110"><template #default="{row}"><el-tag v-if="row.agentStatus==='ESCALATED'" type="danger">待人工处理</el-tag><el-tag v-else-if="row.agentStatus==='AUTO_REPLIED'" type="success">AI 已回复</el-tag><span v-else>—</span></template></el-table-column><el-table-column label="类型" width="100"><template #default="{row}">{{typeLabel[row.type as FeedbackType]}}</template></el-table-column><el-table-column label="标题" prop="title" min-width="220"/><el-table-column label="用户" min-width="140"><template #default="{row}">{{row.userName||row.userAccount||row.userId}}</template></el-table-column><el-table-column label="题号" prop="problemNo" width="80"/><el-table-column label="提交时间" width="175"><template #default="{row}">{{formatShanghai(row.createTime)}}</template></el-table-column></el-table></section>
  <div v-if="query.data.value" class="pager"><el-pagination v-model:current-page="page" :page-size="20" :total="query.data.value.total" layout="total,prev,pager,next" @current-change="query.refetch()"/></div>
  <el-drawer v-model="drawer" title="处理反馈" size="min(620px,92vw)"><template v-if="selected"><div class="meta"><el-tag>{{statusLabel[selected.status]}}</el-tag><el-tag v-if="selected.agentStatus==='ESCALATED'" type="danger">AI 转人工</el-tag><el-tag v-else-if="selected.replySource==='AI'" type="success">AI 已自动回复</el-tag><span>{{typeLabel[selected.type]}}</span><span>用户：{{selected.userName||selected.userAccount||selected.userId}}</span><span v-if="selected.problemNo">题号 {{selected.problemNo}}</span></div><h2>{{selected.title}}</h2><p class="content">{{selected.content}}</p><el-divider/><el-form label-position="top"><el-form-item label="处理状态"><el-radio-group v-model="handling.status"><el-radio-button value="PROCESSING">处理中</el-radio-button><el-radio-button value="RESOLVED">已解决</el-radio-button></el-radio-group></el-form-item><el-form-item label="管理员回复" :required="handling.status==='RESOLVED'"><el-input v-model="handling.adminReply" type="textarea" :rows="8" maxlength="4000" show-word-limit/></el-form-item><el-button type="primary" :loading="busy" @click="save">保存处理结果</el-button></el-form></template></el-drawer>
</div></template>
<style scoped>.admin-feedback{max-width:1280px}.filters{display:grid;grid-template-columns:160px 160px 110px minmax(150px,1fr) auto;gap:12px;padding:16px;margin-bottom:16px}.table-shell{overflow:hidden}.table-shell :deep(.el-table__row){cursor:pointer}.pager{display:flex;justify-content:flex-end;margin-top:18px}.meta{display:flex;gap:12px;align-items:center;flex-wrap:wrap;color:var(--oj-text-muted);font-size:13px}.content{white-space:pre-wrap;line-height:1.75;padding:16px;background:var(--oj-surface-soft);border:1px solid var(--oj-border);border-radius:10px}@media(max-width:850px){.filters{grid-template-columns:1fr 1fr}}</style>
